/* 表格容器 - 核心滚动条实现 */
        .table-scroll-container {
            width: 100%;
            overflow-x: auto; /* 允许横向滚动 */
            margin: 2rem 0;
            border-radius: 8px;
            box-shadow: 0 2px 8px rgba(0, 0, 0, 0.05);
            -webkit-overflow-scrolling: touch; /* 优化移动端滚动体验 */
        }


        /* 表格基础样式 */
        table {
            width: 100%;
            border-collapse: collapse;
            background-color: #fff;
        }

        /* 为宽表格设置最小宽度 */
        .table-scroll-container.wide-table table {
            min-width: 800px;
        }

        /* 为窄表格设置自适应宽度 */
        .table-scroll-container.narrow-table table {
            min-width: auto;
        }

        .narrow-table-container {
            display: flex;
            justify-content: center;
        }

        .narrow-table-container .table-scroll-container {
            width: auto;
        }

        /* 表头样式 */
        th {
            background-color: #F3FAFC;
            color: #2c3e50;
            font-weight: 600;
            text-align: left;
            padding: 1rem 1.25rem;
            border-bottom: 2px solid #e0e6f4;
            white-space: nowrap; /* 防止表头文字换行 */
            font-size: 0.95rem;
            text-transform: uppercase;
            letter-spacing: 0.5px;
        }

        /* 表格单元格样式 */
        td {
            padding: 1rem 1.25rem;
            border-bottom: 1px solid #f0f0f0;
            vertical-align: top;
            color: #444;
