        }

        /* 添加列间竖线 - 关键部分 */
        /* 为除了最后一列外的所有th和td添加右边框（竖线） */
        th:not(:last-child), td:not(:last-child) {
            border-right: 1px solid #eaeaea; /* 浅灰色竖线，不明显但清晰 */
        }

        /* 为表头单元格添加更明显的竖线分隔 */
        th:not(:last-child) {
            border-right: 1px solid #d0d7f0; /* 表头竖线略深一点 */
