                border-right: 1px solid #f0f0f0;
            }

            th:not(:last-child) {
                border-right: 1px solid #e0e6f4;
            }

            /* 手机端窄表格处理 */
            .narrow-table-container {
                justify-content: flex-start;
            }

            .narrow-table-container .table-scroll-container {
                width: 100%;
            }
        }

        /* 电脑端隐藏滚动提示 */
        @media (min-width: 769px) {
